from __future__ import annotations

from typing import Any

import reflex as rx

from .api import api
from .editor import cell_editor
from .state import OUTPUT_HEADER_HEIGHT, OUTPUT_ROW_HEIGHT, State

BG_DIM, BG0, BG1, BG2, BG4 = "#232a2e", "#2d353b", "#343f44", "#3d484d", "#4f585e"
FG, BLUE, GREY1, GREY2 = "#d3c6aa", "#7fbbb3", "#859289", "#9da9a0"
ICON_AI, ICON_PY = "\U000f06a9", ""
# The editor fetches completions straight from the backend (see api.py).
COMPLETE_URL = rx.config.get_config().api_url + "/complete"

GRID_THEME = {
    "accent_color": BLUE,
    "accent_fg": BG0,
    "accent_light": "rgba(127, 187, 179, 0.16)",
    "bg_cell": BG0,
    "bg_cell_medium": BG1,
    "bg_header": BG1,
    "bg_header_has_focus": BG2,
    "bg_header_hovered": BG2,
    "border_color": BG2,
    "horizontal_border_color": BG2,
    "header_bottom_border_color": BG4,
    "text_dark": FG,
    "text_medium": GREY2,
    "text_light": GREY1,
    "text_header": FG,
    "text_header_selected": BG0,
    "font_family": "JetBrainsMono Nerd Font, JetBrains Mono, monospace",
    "base_font_style": "13px",
    "header_font_style": "600 13px",
}

# Polars-notebook-style headers: column name, then its dtype in italics on the line below.
# The grid only draws one-line headers, so a canvas callback draws both. The grid copies only
# its own known column fields, so the dtype is looked up in the columns value by index;
# columns without one (eg the row-number column, index -1) fall back to the default drawing.
_DRAW_HEADER_JS = """((args, drawContent) => {
  const column = (COLUMNS)[args.columnIndex];
  if (!column || !column.dtype) return drawContent();
  const { ctx, theme, rect } = args;
  const x = rect.x + theme.cellHorizontalPadding;
  ctx.textBaseline = "middle";
  ctx.textAlign = "left";
  ctx.fillStyle = theme.textHeader;
  ctx.font = theme.headerFontFull;
  ctx.fillText(column.title, x, rect.y + rect.height * 0.34);
  ctx.fillStyle = theme.textLight;
  ctx.font = "italic " + theme.baseFontFull;
  ctx.fillText(column.dtype, x, rect.y + rect.height * 0.72);
})"""


def draw_header(columns: rx.Var) -> rx.Var:
    """The grid's drawHeader callback for these columns (keeps the columns Var's state dependency)."""
    return rx.Var(_DRAW_HEADER_JS.replace("COLUMNS", str(columns)), _var_data=columns._get_all_var_data())


# Cell result grids: same look, smaller type and padding so a result stays compact.
CELL_GRID_THEME = {
    **GRID_THEME,
    "base_font_style": "12px",
    "header_font_style": "600 12px",
    "cell_horizontal_padding": 8,
    "cell_vertical_padding": 2,
}


def handle(name: rx.Var | str) -> rx.Component:
    """A named table that both the agent and the Python cells can refer to."""
    return rx.el.span(name, class_name="handle mono")


def chat_item(item: rx.Var) -> rx.Component:
    return rx.match(
        item["kind"],
        ("user", rx.el.div(item["text"], class_name="bubble is-user")),
        (
            "step",
            rx.el.div(
                rx.el.span("▸", class_name="dim"),
                rx.el.span(item["name"], class_name="tool-name"),
                rx.el.span(item["text"], class_name="tool-args"),
                class_name="tool-step mono",
            ),
        ),
        (
            "ref",
            rx.el.button(
                handle(item["name"]),
                rx.el.span(item["text"], class_name="dim"),
                rx.el.span("open →", class_name="ref-open"),
                on_click=State.select_object(item["name"]),
                class_name="ref",
            ),
        ),
        ("error", rx.el.pre(item["text"], class_name="bubble is-error mono")),
        rx.el.div(rx.markdown(item["text"]), class_name="bubble md"),
    )


def chat_pane() -> rx.Component:
    return rx.el.div(
        rx.el.div("Chat", class_name="pane-title"),
        # column-reverse keeps the scroll pinned to the newest message
        rx.el.div(
            rx.el.div(
                rx.cond(
                    State.chat.length() == 0,
                    rx.el.div(
                        "Ask about Smash Ultimate. Tables the agent pulls show up on the right as r1, r2, … ",
                        "and are plain polars DataFrames in the Python cells.",
                        class_name="empty",
                    ),
                ),
                rx.foreach(State.chat, chat_item),
                rx.cond(
                    State.busy,
                    rx.cond(
                        State.streaming != "",
                        rx.el.div(rx.markdown(State.streaming), class_name="bubble md"),
                        rx.el.div("working…", class_name="bubble dim"),
                    ),
                ),
                class_name="chat-items",
            ),
            class_name="chat-scroll",
        ),
        rx.el.form(
            rx.el.textarea(
                name="prompt",
                placeholder="Ask the agent…  (Enter to send, Shift+Enter for a new line)",
                enter_key_submit=True,
                rows=2,
                class_name="input sans",
            ),
            on_submit=State.send_chat,
            reset_on_submit=True,
            class_name="composer",
        ),
        class_name="chat-pane sans",
    )


def object_tab(obj: rx.Var) -> rx.Component:
    return rx.el.button(
        handle(obj["name"]),
        rx.el.span(obj["shape"]),
        rx.el.span(obj["source"], class_name="dim"),
        on_click=State.select_object(obj["name"]),
        class_name=rx.cond(State.selected == obj["name"], "tab is-active", "tab"),
    )


def viewer() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            handle(State.selected),
            rx.el.span(State.grid_note, class_name="dim"),
            rx.el.span(class_name="spacer"),
            rx.el.input(
                placeholder="Filter rows…",
                value=State.query,
                on_change=State.set_query,
                class_name="viewer-filter",
            ),
            class_name="viewer-bar sans",
        ),
        rx.el.div(
            rx.data_editor(
                columns=State.columns,
                data=State.rows,
                rows=State.row_count,
                theme=GRID_THEME,
                row_markers="number",
                row_height=28,
                header_height=44,
                smooth_scroll_x=True,
                smooth_scroll_y=True,
                column_select="none",
                on_header_clicked=State.header_clicked,
                custom_attrs={"drawHeader": draw_header(State.columns)},
                height="100%",
            ),
            class_name="viewer-grid",
        ),
        class_name="widget",
    )


@rx.memo
def output_grid(
    cell_id: rx.Var[str],
    columns: rx.Var[list[dict[str, Any]]],
    rows: rx.Var[list[list[Any]]],
    height: rx.Var[str],
) -> rx.Component:
    """A cell's tabular result in the same grid as the tables pane.

    A memo component gives each cell's grid its own scope; the grid's data callback is
    generated outside the cells loop and couldn't see a loop item otherwise.
    """
    return rx.el.div(
        rx.data_editor(
            columns=columns,
            data=rows,
            rows=rows.length(),
            theme=CELL_GRID_THEME,
            row_markers="number",
            row_height=OUTPUT_ROW_HEIGHT,
            header_height=OUTPUT_HEADER_HEIGHT,
            smooth_scroll_x=True,
            smooth_scroll_y=True,
            column_select="none",
            on_header_clicked=lambda pos: State.sort_output(cell_id, pos),
            custom_attrs={"drawHeader": draw_header(columns)},
            height="100%",
        ),
        style={"height": height},
        class_name="cell-grid",
    )


def cell_view(cell: rx.Var) -> rx.Component:
    """One notebook cell: In[n] gutter, CodeMirror editor, output underneath."""
    return rx.el.div(
        rx.el.div(
            rx.el.span("[", rx.cond(cell.count == "", " ", cell.count), "]", class_name="cell-count mono"),
            rx.el.div(
                cell_editor(
                    initial_code=cell.code,
                    complete_url=COMPLETE_URL,
                    token=State.token,
                    on_run=lambda code, advance: State.run_cell(cell.id, code, advance),
                    on_save=lambda code: State.save_code(cell.id, code),
                ),
                class_name="cell-editor",
            ),
            rx.el.button("▶", title="Run (Ctrl+Enter)", on_click=State.run_saved(cell.id), class_name="cell-btn"),
            rx.el.button("×", title="Delete cell", on_click=State.delete_cell(cell.id), class_name="cell-btn"),
            class_name="cell-in",
        ),
        rx.cond(cell.stdout != "", rx.el.pre(cell.stdout, class_name="cell-out mono")),
        rx.cond(
            cell.columns.length() > 0,
            rx.el.div(
                rx.el.div(
                    rx.el.span("DataFrame", class_name="out-kind"),
                    rx.el.span(cell.note, class_name="dim"),
                    rx.el.span(class_name="spacer"),
                    rx.el.button(
                        "↗ tab",
                        title="Open as a tab above, with filter (bound as out<n>)",
                        on_click=State.open_output(cell.id),
                        class_name="act",
                    ),
                    title="Click a column header to sort",
                    class_name="out-bar sans",
                ),
                output_grid(cell_id=cell.id, columns=cell.columns, rows=cell.rows, height=cell.height),
                style={"width": cell.width},
                class_name="widget cell-widget",
            ),
        ),
        rx.cond(cell.text != "", rx.el.pre(cell.text, class_name="cell-out mono")),
        rx.cond(cell.error != "", rx.el.pre(cell.error, class_name="cell-out is-error mono")),
        key=cell.id,
        class_name="cell",
    )


def notebook() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span(rx.el.span(ICON_PY, class_name="mono accent-green icon"), "Python"),
            rx.el.span(
                "Shift+Enter run and advance · Ctrl+Enter run · Tab complete",
                class_name="dim",
            ),
            rx.el.span(class_name="spacer"),
            rx.cond(State.running, rx.el.span("running…", class_name="dim")),
            rx.el.button("Run all", on_click=State.run_all, class_name="act"),
            rx.el.button("Clear outputs", on_click=State.clear_outputs, class_name="act"),
            rx.el.button("+ Cell", on_click=State.add_cell, class_name="act"),
            class_name="console-head sans",
        ),
        rx.el.div(rx.foreach(State.cells, cell_view), class_name="notebook-body"),
        class_name="console",
    )


def workspace() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.foreach(State.objects, object_tab),
            rx.cond(~State.has_objects, rx.el.span("no tables yet", class_name="tab dim")),
            class_name="tabbar sans",
        ),
        rx.el.div(
            rx.cond(
                State.has_objects,
                viewer(),
                rx.el.div(
                    "Tables appear here when the agent pulls data, or when you make a DataFrame below, eg ",
                    rx.el.code('chars = db.sql("select * from char")'),
                    class_name="empty sans",
                ),
            ),
            # with no tables yet, the notebook gets the height
            class_name=rx.cond(State.has_objects, "ws-widget", "ws-widget is-empty"),
        ),
        notebook(),
        class_name="ws-pane",
    )


def index() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span("SmashGPT", class_name="title"),
            rx.el.span(class_name="spacer"),
            rx.cond(State.busy, rx.el.span(rx.el.span(ICON_AI, class_name="mono accent-red icon"), "agent working…")),
            class_name="titlebar sans",
        ),
        rx.el.div(chat_pane(), workspace(), class_name="split-main"),
        class_name="page",
    )


# theme=None: no Radix theme wrapper, all styling comes from assets/app.css.
app = rx.App(
    theme=None,
    stylesheets=["/app.css"],
    api_transformer=api,
    head_components=[
        rx.el.link(rel="icon", href="/favicon.png", type="image/png"),
        rx.el.link(rel="apple-touch-icon", href="/apple-touch-icon.png"),
    ],
)
# The page title is the web app window's title (SmashGPT); see .os/scripts/keybindings/smashgpt.py.
app.add_page(index, route="/", title="SmashGPT", on_load=State.on_load)
